from typing import Any, Literal, Annotated
from pydantic import BaseModel
from fastapi import FastAPI, Body
from fastapi.testclient import TestClient

class Pie(BaseModel):
    time_to_cook: int
    num_ingredients: int

class ApplePie(Pie):
    fruit: Literal["apple"] = "apple"

class PumpkinPie(Pie):
    filling: Literal["pumpkin"] = "pumpkin"

def get_discriminator_value(v: Any) -> str:
    if isinstance(v, dict):
        return v.get("fruit", v.get("filling"))
    return getattr(v, "fruit", getattr(v, "filling", None))

# This is the problematic type
# Note: Tag and Discriminator are likely from pydantic or some other library, 
# but in the issue description they are used. 
# Wait, Tag and Discriminator are not standard pydantic. 
# Let me check if they are from pydantic or if I need to define them.
# Actually, Pydantic v2 has Discriminator. 
# Let's see if I can import them.
try:
    from pydantic import Discriminator, Tag
except ImportError:
    # If they are not available, I might need to mock them or find where they come from.
    # But the issue says "tagged discriminated union", which is a Pydantic v2 feature.
    # Let's try to define them as simple classes if they are missing, 
    # but they should be there if pydantic v2 is installed.
    class Tag:
        def __init__(self, value): self.value = value
    class Discriminator:
        def __init__(self, value): self.value = value

Dessert = Annotated[
    Annotated[ApplePie, Tag("apple")] | Annotated[PumpkinPie, Tag("pumpkin")],
    Discriminator(get_discriminator_value),
]

app = FastAPI()

@app.post("/dessert")
async def dinner(dessert: Dessert) -> dict[str, Any]:
    return dessert.model_dump()

client = TestClient(app)

def test_dessert_endpoint():
    # This should be a body parameter
    response = client.post("/dessert", json={"fruit": "apple", "time_to_cook": 10, "num_ingredients": 3})
    assert response.status_code == 200
    assert response.json() == {"fruit": "apple", "time_to_cook": 10, "num_ingredients": 3}

    response = client.post("/dessert", json={"filling": "pumpkin", "time_to_cook": 20, "num_ingredients": 5})
    assert response.status_code == 200
    assert response.json() == {"filling": "pumpkin", "time_to_cook": 20, "num_ingredients": 5}

if __name__ == "__main__":
    try:
        test_dessert_endpoint()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        import traceback
        traceback.print_exc()

